import Foundation

// MARK: - Feature Flag System
struct FeatureFlags {
    static var enableRateLimiting: Bool = true
    static var enableBatchProcessing: Bool = true
    static var maxBatchSize: Int = 10
    static var rateLimitWindow: TimeInterval = 60.0
    static var maxTransactionsPerWindow: Int = 5
}

// MARK: - Transaction Model
struct Transaction {
    let sender: String
    let recipient: String
    let amount: UInt64
    let timestamp: Date
    let nonce: UInt64
    let isBatched: Bool

    var id: String {
        return "\(sender):\(nonce):\(timestamp.timeIntervalSince1970)"
    }
}

// MARK: - Rate Limiter
class RateLimiter {
    private var transactionLog: [String: [Date]] = [:]
    private let lock = NSLock()

    func isAllowed(sender: String, at time: Date) -> Bool {
        lock.lock()
        defer { lock.unlock() }

        guard FeatureFlags.enableRateLimiting else {
            return true
        }

        let windowStart = time.addingTimeInterval(-FeatureFlags.rateLimitWindow)

        // Clean old entries
        if var logs = transactionLog[sender] {
            logs = logs.filter { $0 > windowStart }
            transactionLog[sender] = logs

            if logs.count >= FeatureFlags.maxTransactionsPerWindow {
                return false
            }
        }

        return true
    }

    func record(sender: String, at time: Date) {
        lock.lock()
        defer { lock.unlock() }

        if transactionLog[sender] == nil {
            transactionLog[sender] = []
        }
        transactionLog[sender]?.append(time)
    }

    func recordBatch(sender: String, count: Int, at time: Date) {
        lock.lock()
        defer { lock.unlock() }

        if transactionLog[sender] == nil {
            transactionLog[sender] = []
        }
        // Record batch as single entry for efficiency
        transactionLog[sender]?.append(time)
    }
}

// MARK: - Smart Contract
class TokenTransferContract {
    private var balances: [String: UInt64] = [:]
    private let rateLimiter = RateLimiter()
    private var processedNonces: [String: Set<UInt64>] = [:]
    private let contractLock = NSLock()

    init() {
        // Genesis allocation
        balances["treasury"] = 1_000_000_000
    }

    func getBalance(of address: String) -> UInt64 {
        contractLock.lock()
        defer { contractLock.unlock() }
        return balances[address] ?? 0
    }

    // MARK: - Single Transaction Processing
    func processTransaction(_ tx: Transaction) -> Result<String, ContractError> {
        guard !tx.isBatched else {
            return .failure(.invalidContext("Use processBatch for batched transactions"))
        }

        // Rate limit check
        guard rateLimiter.isAllowed(sender: tx.sender, at: tx.timestamp) else {
            return .failure(.rateLimited("Exceeded \(FeatureFlags.maxTransactionsPerWindow) transactions per window"))
        }

        let result = executeTransfer(tx)
        if case .success = result {
            rateLimiter.record(sender: tx.sender, at: tx.timestamp)
        }
        return result
    }

    // MARK: - Batch Transaction Processing
    func processBatch(_ transactions: [Transaction]) -> Result<[String], ContractError> {
        guard FeatureFlags.enableBatchProcessing else {
            return .failure(.featureDisabled("Batch processing is disabled"))
        }

        guard transactions.count <= FeatureFlags.maxBatchSize else {
            return .failure(.batchTooLarge("Max batch size: \(FeatureFlags.maxBatchSize)"))
        }

        guard let firstTx = transactions.first else {
            return .failure(.emptyBatch)
        }

        let sender = firstTx.sender

        // Verify all transactions are from same sender and marked as batched
        guard transactions.allSatisfy({ $0.sender == sender && $0.isBatched }) else {
            return .failure(.invalidBatch("All transactions must be from same sender and marked as batched"))
        }

        // Rate limit check for batch - check if sender is allowed
        guard rateLimiter.isAllowed(sender: sender, at: firstTx.timestamp) else {
            return .failure(.rateLimited("Sender rate limited"))
        }

        var results: [String] = []
        for tx in transactions {
            let result = executeTransfer(tx)
            switch result {
            case .success(let txId):
                results.append(txId)
            case .failure(let error):
                return .failure(error)
            }
        }

        // Record the batch as a single rate limit entry
        rateLimiter.recordBatch(sender: sender, count: transactions.count, at: firstTx.timestamp)

        return .success(results)
    }

    // MARK: - Core Transfer Logic
    private func executeTransfer(_ tx: Transaction) -> Result<String, ContractError> {
        contractLock.lock()
        defer { contractLock.unlock() }

        // Nonce replay protection
        if processedNonces[tx.sender]?.contains(tx.nonce) == true {
            return .failure(.nonceReused("Nonce \(tx.nonce) already used"))
        }

        // Balance check
        let senderBalance = balances[tx.sender] ?? 0
        guard senderBalance >= tx.amount else {
            return .failure(.insufficientBalance("Need \(tx.amount), have \(senderBalance)"))
        }

        guard tx.amount > 0 else {
            return .failure(.invalidAmount("Amount must be positive"))
        }

        // Execute transfer
        balances[tx.sender] = senderBalance - tx.amount
        balances[tx.recipient] = (balances[tx.recipient] ?? 0) + tx.amount

        // Record nonce
        if processedNonces[tx.sender] == nil {
            processedNonces[tx.sender] = Set<UInt64>()
        }
        processedNonces[tx.sender]?.insert(tx.nonce)

        return .success(tx.id)
    }
}

// MARK: - Errors
enum ContractError: Error {
    case rateLimited(String)
    case insufficientBalance(String)
    case invalidAmount(String)
    case nonceReused(String)
    case featureDisabled(String)
    case batchTooLarge(String)
    case invalidBatch(String)
    case invalidContext(String)
    case emptyBatch
}
